-- Version 1: normalized business records. Monetary values are integer cents.
CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,name TEXT NOT NULL,checksum TEXT NOT NULL,applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS clinics(id TEXT PRIMARY KEY,name TEXT NOT NULL,address TEXT NOT NULL,supervisor TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,area REAL NOT NULL CHECK(area>0),active INTEGER NOT NULL CHECK(active IN(0,1)),version INTEGER NOT NULL CHECK(version>0));
CREATE TABLE IF NOT EXISTS dentists(id TEXT PRIMARY KEY,employee_no TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,dob TEXT,phone TEXT NOT NULL,email TEXT,address TEXT NOT NULL,active INTEGER NOT NULL CHECK(active IN(0,1)),version INTEGER NOT NULL CHECK(version>0));
CREATE TABLE IF NOT EXISTS qualifications(id TEXT PRIMARY KEY,name TEXT NOT NULL,issuer TEXT NOT NULL,description TEXT,active INTEGER NOT NULL CHECK(active IN(0,1)),version INTEGER NOT NULL CHECK(version>0));
CREATE TABLE IF NOT EXISTS dentist_qualifications(dentist_id TEXT NOT NULL REFERENCES dentists(id) ON DELETE CASCADE,qualification_id TEXT NOT NULL REFERENCES qualifications(id),position INTEGER NOT NULL,PRIMARY KEY(dentist_id,qualification_id));
CREATE TABLE IF NOT EXISTS dentist_qualification_details(dentist_id TEXT NOT NULL REFERENCES dentists(id) ON DELETE CASCADE,qualification_id TEXT NOT NULL REFERENCES qualifications(id),certificate_no TEXT,verified_at TEXT,verified_by TEXT,note TEXT,position INTEGER NOT NULL,PRIMARY KEY(dentist_id,qualification_id));
CREATE TABLE IF NOT EXISTS treatments(id TEXT PRIMARY KEY,name TEXT NOT NULL,unit TEXT NOT NULL,unit_price INTEGER NOT NULL CHECK(unit_price>=0),active INTEGER NOT NULL CHECK(active IN(0,1)),version INTEGER NOT NULL CHECK(version>0));
CREATE TABLE IF NOT EXISTS patients(id TEXT PRIMARY KEY,name TEXT NOT NULL,dob TEXT,phone TEXT NOT NULL,phone_normalized TEXT GENERATED ALWAYS AS(replace(replace(phone,' ',''),'-','')) STORED,email TEXT,address TEXT,emergency_name TEXT,emergency_phone TEXT,allergy_status TEXT NOT NULL CHECK(allergy_status IN('unknown','none','known')),allergy_declared_at TEXT,allergy_verified_by TEXT,allergy_verified_at TEXT,allergy_source TEXT,created_clinic_id TEXT REFERENCES clinics(id),created_at TEXT,active INTEGER CHECK(active IN(0,1)),merged_into_id TEXT REFERENCES patients(id),version INTEGER NOT NULL CHECK(version>0));
CREATE INDEX IF NOT EXISTS patients_identity ON patients(phone_normalized,dob);
CREATE INDEX IF NOT EXISTS patients_clinic ON patients(created_clinic_id);
CREATE TABLE IF NOT EXISTS patient_allergies(patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,id TEXT NOT NULL,name TEXT NOT NULL,reaction TEXT,note TEXT,position INTEGER NOT NULL,PRIMARY KEY(patient_id,id));
CREATE TABLE IF NOT EXISTS patient_clinic_access(patient_id TEXT NOT NULL REFERENCES patients(id) ON DELETE CASCADE,clinic_id TEXT NOT NULL REFERENCES clinics(id),position INTEGER NOT NULL,PRIMARY KEY(patient_id,clinic_id));
CREATE TABLE IF NOT EXISTS schedules(id TEXT PRIMARY KEY,clinic_id TEXT NOT NULL REFERENCES clinics(id),dentist_id TEXT NOT NULL REFERENCES dentists(id),start_at TEXT NOT NULL,end_at TEXT NOT NULL CHECK(end_at>start_at),capacity INTEGER NOT NULL CHECK(capacity=1),active INTEGER NOT NULL CHECK(active IN(0,1)),version INTEGER NOT NULL CHECK(version>0));
CREATE INDEX IF NOT EXISTS schedules_dentist_time ON schedules(dentist_id,start_at,end_at);
CREATE INDEX IF NOT EXISTS schedules_clinic_time ON schedules(clinic_id,start_at,end_at);
CREATE TABLE IF NOT EXISTS appointments(id TEXT PRIMARY KEY,patient_id TEXT NOT NULL REFERENCES patients(id),clinic_id TEXT NOT NULL REFERENCES clinics(id),dentist_id TEXT NOT NULL REFERENCES dentists(id),schedule_id TEXT NOT NULL REFERENCES schedules(id),start_at TEXT NOT NULL,end_at TEXT NOT NULL CHECK(end_at>start_at),problem TEXT NOT NULL,special_needs TEXT,status TEXT NOT NULL CHECK(status IN('booked','attended','no_show','cancelled')),attended INTEGER NOT NULL CHECK(attended IN(0,1)),previous_id TEXT REFERENCES appointments(id),created_at TEXT,cancel_reason TEXT,cancelled_at TEXT,status_reason TEXT,status_changed_at TEXT,version INTEGER NOT NULL CHECK(version>0));
CREATE INDEX IF NOT EXISTS appointments_slot_status ON appointments(schedule_id,status);
CREATE INDEX IF NOT EXISTS appointments_patient ON appointments(patient_id,start_at,end_at);
CREATE INDEX IF NOT EXISTS appointments_dentist_time ON appointments(dentist_id,start_at,end_at,status);
CREATE INDEX IF NOT EXISTS appointments_clinic_time ON appointments(clinic_id,start_at,end_at);
CREATE TABLE IF NOT EXISTS visits(id TEXT PRIMARY KEY,appointment_id TEXT NOT NULL UNIQUE REFERENCES appointments(id),patient_id TEXT NOT NULL REFERENCES patients(id),clinic_id TEXT NOT NULL REFERENCES clinics(id),dentist_id TEXT NOT NULL REFERENCES dentists(id),problem TEXT,special_needs TEXT,notes TEXT,status TEXT NOT NULL CHECK(status IN('open','completed')),completed_at TEXT,version INTEGER NOT NULL CHECK(version>0));
CREATE INDEX IF NOT EXISTS visits_patient ON visits(patient_id);
CREATE INDEX IF NOT EXISTS visits_clinic ON visits(clinic_id,dentist_id,status);
CREATE TABLE IF NOT EXISTS visit_lines(visit_id TEXT NOT NULL REFERENCES visits(id) ON DELETE CASCADE,id TEXT NOT NULL,treatment_id TEXT NOT NULL REFERENCES treatments(id),name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 1000),unit_price INTEGER NOT NULL CHECK(unit_price>=0),position INTEGER NOT NULL,PRIMARY KEY(visit_id,id),UNIQUE(visit_id,treatment_id));
CREATE TABLE IF NOT EXISTS settlements(id TEXT PRIMARY KEY,number TEXT NOT NULL UNIQUE,visit_id TEXT NOT NULL UNIQUE REFERENCES visits(id),patient_id TEXT NOT NULL REFERENCES patients(id),clinic_id TEXT NOT NULL REFERENCES clinics(id),dentist_id TEXT NOT NULL REFERENCES dentists(id),date TEXT NOT NULL,total INTEGER NOT NULL CHECK(total>=0),version INTEGER NOT NULL CHECK(version>0));
CREATE INDEX IF NOT EXISTS settlements_patient ON settlements(patient_id,date);
CREATE INDEX IF NOT EXISTS settlements_clinic_date ON settlements(clinic_id,date,dentist_id);
CREATE TABLE IF NOT EXISTS settlement_lines(settlement_id TEXT NOT NULL REFERENCES settlements(id) ON DELETE CASCADE,position INTEGER NOT NULL,id TEXT,treatment_id TEXT REFERENCES treatments(id),name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price INTEGER NOT NULL CHECK(unit_price>=0),subtotal INTEGER NOT NULL CHECK(subtotal=quantity*unit_price),PRIMARY KEY(settlement_id,position));
CREATE TABLE IF NOT EXISTS costs(id TEXT PRIMARY KEY,quarter TEXT NOT NULL,clinic_id TEXT NOT NULL REFERENCES clinics(id),dentist_id TEXT NOT NULL REFERENCES dentists(id),supplies INTEGER NOT NULL CHECK(supplies>=0),operations INTEGER NOT NULL CHECK(operations>=0),evidence TEXT,note TEXT,status TEXT NOT NULL CHECK(status IN('draft','reviewed')),reviewed_by TEXT,reviewed_at TEXT,version INTEGER NOT NULL CHECK(version>0),UNIQUE(quarter,clinic_id,dentist_id));
CREATE INDEX IF NOT EXISTS costs_quarter ON costs(quarter,status);
CREATE TABLE IF NOT EXISTS cost_review_history(cost_id TEXT NOT NULL REFERENCES costs(id) ON DELETE CASCADE,position INTEGER NOT NULL,at TEXT,user_id TEXT,action TEXT,version INTEGER,PRIMARY KEY(cost_id,position));
CREATE TABLE IF NOT EXISTS quarterReports(id TEXT PRIMARY KEY,quarter TEXT NOT NULL,revenue INTEGER NOT NULL,supplies INTEGER NOT NULL,operations INTEGER NOT NULL,net_profit INTEGER NOT NULL,fund INTEGER NOT NULL CHECK(fund>=0),fund_rate REAL NOT NULL,negative_profit_policy TEXT,revenue_basis TEXT,status TEXT NOT NULL CHECK(status IN('draft','approved')),created_at TEXT,scope TEXT,source_signature TEXT,approved_by TEXT,approved_at TEXT,invalidated_at TEXT,invalidated_reason TEXT,version INTEGER NOT NULL CHECK(version>0));
CREATE INDEX IF NOT EXISTS quarter_reports_quarter ON quarterReports(quarter,status);
CREATE TABLE IF NOT EXISTS quarter_report_clinics(report_id TEXT NOT NULL REFERENCES quarterReports(id) ON DELETE CASCADE,clinic_id TEXT NOT NULL REFERENCES clinics(id),position INTEGER NOT NULL,PRIMARY KEY(report_id,clinic_id));
CREATE TABLE IF NOT EXISTS quarter_report_rows(report_id TEXT NOT NULL REFERENCES quarterReports(id) ON DELETE CASCADE,position INTEGER NOT NULL,clinic_id TEXT NOT NULL REFERENCES clinics(id),dentist_id TEXT NOT NULL REFERENCES dentists(id),revenue INTEGER NOT NULL,supplies INTEGER NOT NULL,operations INTEGER NOT NULL,net_profit INTEGER NOT NULL,cost_id TEXT REFERENCES costs(id),cost_version INTEGER,PRIMARY KEY(report_id,position));
CREATE TABLE IF NOT EXISTS quarter_report_settlements(report_id TEXT NOT NULL,position INTEGER NOT NULL,settlement_id TEXT NOT NULL REFERENCES settlements(id),item_position INTEGER NOT NULL,FOREIGN KEY(report_id,position) REFERENCES quarter_report_rows(report_id,position) ON DELETE CASCADE,PRIMARY KEY(report_id,position,settlement_id));
CREATE TABLE IF NOT EXISTS quarter_report_history(report_id TEXT NOT NULL REFERENCES quarterReports(id) ON DELETE CASCADE,position INTEGER NOT NULL,at TEXT,action TEXT,user_id TEXT,version INTEGER,prior_status TEXT,prior_version INTEGER,PRIMARY KEY(report_id,position));
CREATE TABLE IF NOT EXISTS settings(id TEXT PRIMARY KEY,cancellation_hours INTEGER NOT NULL CHECK(cancellation_hours BETWEEN 0 AND 168),fund_rate REAL NOT NULL CHECK(fund_rate>=0 AND fund_rate<=1),version INTEGER NOT NULL CHECK(version>0));
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE COLLATE NOCASE,password_hash TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),role TEXT,name TEXT,patient_id TEXT,dentist_id TEXT,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE INDEX IF NOT EXISTS users_patient ON users(patient_id);
CREATE INDEX IF NOT EXISTS users_role_active ON users(role,active);
CREATE TRIGGER IF NOT EXISTS users_sync_insert AFTER INSERT ON users BEGIN UPDATE users SET role=json_extract(NEW.data,'$.role'),name=json_extract(NEW.data,'$.name'),patient_id=json_extract(NEW.data,'$.patientId'),dentist_id=json_extract(NEW.data,'$.dentistId'),active=CASE WHEN json_extract(NEW.data,'$.active')=0 THEN 0 ELSE 1 END WHERE id=NEW.id; END;
CREATE TRIGGER IF NOT EXISTS users_sync_update AFTER UPDATE OF data ON users BEGIN UPDATE users SET role=json_extract(NEW.data,'$.role'),name=json_extract(NEW.data,'$.name'),patient_id=json_extract(NEW.data,'$.patientId'),dentist_id=json_extract(NEW.data,'$.dentistId'),active=CASE WHEN json_extract(NEW.data,'$.active')=0 THEN 0 ELSE 1 END WHERE id=NEW.id; END;
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS idempotency_requests(user_id TEXT NOT NULL REFERENCES users(id),key TEXT NOT NULL,request_hash TEXT NOT NULL,response TEXT NOT NULL CHECK(json_valid(response)),created_at INTEGER NOT NULL,PRIMARY KEY(user_id,key));
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,at TEXT NOT NULL,user_id TEXT NOT NULL,type TEXT NOT NULL,target_id TEXT,detail TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_time ON audit(at);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'Audit records are append only'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'Audit records are append only'); END;
